DROP TABLE IF EXISTS `resultados_modelos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `resultados_modelos` (
  `id_resultado` int NOT NULL AUTO_INCREMENT,
  `id_producto` int NOT NULL,
  `EOQ` int DEFAULT NULL,
  `PRO` int DEFAULT NULL,
  `inventario_seguridad` int DEFAULT NULL,
  `fecha_calculo` datetime DEFAULT CURRENT_TIMESTAMP,
  `ventas_anuales` decimal(12,2) DEFAULT NULL,
  `porcentaje` decimal(5,2) DEFAULT NULL,
  `porcentaje_acumulado` decimal(5,2) DEFAULT NULL,
  `costo_anual_ordenar` decimal(12,2) DEFAULT NULL,
  `costo_anual_conservacion` decimal(12,2) DEFAULT NULL,
  `costo_total` decimal(12,2) DEFAULT NULL,
  `punto_reorden` int DEFAULT NULL,
  `clasificacion_ABC` char(1) DEFAULT NULL,
  PRIMARY KEY (`id_resultado`),
  KEY `id_producto` (`id_producto`),
  CONSTRAINT `resultados_modelos_ibfk_1` FOREIGN KEY (`id_producto`) REFERENCES `productos` (`id_producto`)
) ENGINE=InnoDB AUTO_INCREMENT=1003 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
